insert into public.site_settings (id, business_name, short_name, tagline, logo, email, phones, whatsapp, location, socials, footer_note, show_packages, show_prices, show_testimonials, seo) values (1, 'Upright Pictures Concepts', 'UPC', 'Capturing moments, delivering excellence.', '{"src":"/brand/upc-logo.jpg","width":488,"height":511,"alt":"Upright Pictures Concepts monogram"}'::jsonb, 'uprightpictureconcepts@gmail.com', array['08104817424', '09049314932']::text[], '08104817424', 'Lagos, Nigeria', '{"instagram":"https://www.instagram.com/uprightpicturesconcepts","tiktok":"https://www.tiktok.com/@uprightpictureconcepts","youtube":"https://www.youtube.com/@uprightpictureconcepts","x":"https://x.com/BeloveBenChuks"}'::jsonb, 'Delivery is the language of competence.', true, true, true, '{"title":"Upright Pictures Concepts | Photography, Film & Framing in Lagos","description":"Wedding, portrait and event photography, videography, drone coverage, enlargement and framing by Upright Pictures Concepts, Lagos.","image":{"src":"https://images.unsplash.com/photo-1618999114008-fbf937170cdb","width":4000,"height":6000,"alt":"Bride in coral beads and a red and gold crown","credit":"Dennis Irorere"}}'::jsonb);
insert into public.page_content (page, section, data) values ('home', 'hero', '{"headline":"Moments worth","headlineEmphasis":"keeping.","subheadline":"Photography, film and framing for weddings, portraits and celebrations in Lagos and beyond.","primaryCta":"View the work","secondaryCta":"Book a shoot","slides":[{"src":"https://images.unsplash.com/photo-1618999114008-fbf937170cdb","width":4000,"height":6000,"alt":"Bride in coral beads and a red and gold crown","credit":"Dennis Irorere"},{"src":"https://images.unsplash.com/photo-1788035963488-cbfabe82ed4a","width":3851,"height":4814,"alt":"Couple in olive green traditional Nigerian wedding attire","credit":"McFollis"},{"src":"https://images.unsplash.com/photo-1605980776566-0486c3ac7617","width":3933,"height":5090,"alt":"Studio portrait of a man in a black turtleneck","credit":"Veroll Sterling"},{"src":"https://images.unsplash.com/photo-1636144896336-b056be4a8dfe","width":2325,"height":3488,"alt":"Woman in a black suit lit in low light","credit":"Mo Darbz"},{"src":"https://images.unsplash.com/photo-1688143029511-b37423aa60a2","width":4000,"height":6016,"alt":"Man in a white kaftan and embroidered cap on black","credit":"Tolu Akinyemi"}]}'::jsonb);
insert into public.page_content (page, section, data) values ('home', 'intro', '{"statement":"We photograph people at their most honest, then make sure the moment outlives the day.","body":"From the first frame to the finished print, everything happens in-house: shooting, editing, enlargement and framing. One team, start to finish, so nothing gets lost between hand-offs.","image":{"src":"https://images.unsplash.com/photo-1531123897727-8f129e1688ce","width":4000,"height":6000,"alt":"Woman in a printed dress holding her white collar","credit":"Prince Akachi"}}'::jsonb);
insert into public.page_content (page, section, data) values ('home', 'process', '{"heading":"From shoot to frame","intro":"Most studios stop at the download link. We keep going until it is on your wall.","steps":[{"title":"Shoot","body":"Studio, home or venue. We plan the light, the poses and the timeline with you before the day.","image":{"src":"https://images.unsplash.com/photo-1621024994278-e409544f4085","width":2997,"height":4504,"alt":"Photographer shooting with a DSLR in a dark studio","credit":"Colin Lloyd"}},{"title":"Edit","body":"Every image is colour graded and retouched by hand, with your preferences kept on file.","image":{"src":"https://images.unsplash.com/photo-1609034227505-5876f6aa4e90","width":3072,"height":3840,"alt":"Hand holding a camera lens under coloured light","credit":"Amari James"}},{"title":"Print","body":"Enlargements on quality paper and canvas, sized for the space they will live in.","image":{"src":"https://images.unsplash.com/photo-1789841418151-7a5b9a8812e6","width":3259,"height":2185,"alt":"Woman holding two framed prints against a wall","credit":"Barney Goodman"}},{"title":"Frame","body":"Classic, frameless and 3D frames, finished in our workshop and ready to hang.","image":{"src":"https://images.unsplash.com/photo-1781208745207-e8a4c9985de7","width":7728,"height":5052,"alt":"Wall of framed photographs in a warm gallery","credit":"Cristian Pineda"}}]}'::jsonb);
insert into public.page_content (page, section, data) values ('home', 'showreel', '{"heading":"Seen from above","caption":"Aerial photography and film for weddings, events and property.","videoUrl":"","poster":{"src":"https://images.unsplash.com/photo-1765475467677-579353b25ce0","width":8000,"height":6000,"alt":"Boats on the lagoon beside a bridge and the city","credit":"Malik Buraimoh"}}'::jsonb);
insert into public.page_content (page, section, data) values ('home', 'cta', '{"heading":"Have a date in mind?","body":"Tell us about the day. We will reply with availability and a quote, usually within a few hours.","image":{"src":"https://images.unsplash.com/photo-1684253866485-b26f847ff97e","width":3456,"height":5184,"alt":"Black and white portrait of a bride and groom under palm trees","credit":"Elizabeth Pappoe"}}'::jsonb);
insert into public.page_content (page, section, data) values ('about', 'main', '{"heading":"The person behind the lens","lead":"Upright Pictures Concepts is the Lagos studio of Chukwudi Benjamin Mbam Upright: photographer, filmmaker and framer.","story":["What started with a single camera and a lot of weekends at weddings has grown into a studio that covers the whole journey of a photograph, from the moment it is taken to the frame it hangs in.","We work with couples, families, graduates, brands and event planners across Lagos. Some clients come for a one-hour studio session; others trust us with every part of a three-day celebration.","Our promise is simple and printed on every flyer we have ever made: delivery is the language of competence. You get your pictures when we say you will, finished to a standard we are proud to sign."],"portrait":{"src":"https://images.unsplash.com/photo-1666114264360-0427e27ac91d","width":3727,"height":5590,"alt":"Silhouette of a photographer holding a camera","credit":"Mohammadreza Charkhgard"},"secondaryImage":{"src":"https://images.unsplash.com/photo-1781208745207-e8a4c9985de7","width":7728,"height":5052,"alt":"Wall of framed photographs in a warm gallery","credit":"Cristian Pineda"},"stats":[{"value":"9","label":"Services under one roof"},{"value":"In-house","label":"Printing, enlargement and framing"},{"value":"Aerial","label":"Drone coverage on request"}],"values":[{"title":"Honest light","body":"Skin tones that look like you, colour that holds up in print, and no filters that date in a year."},{"title":"On time, every time","body":"Clear timelines agreed upfront. Galleries and prints arrive when we promised."},{"title":"Built to last","body":"Archival printing and solid framing, because the best pictures should outlive their phones."}]}'::jsonb);
insert into public.page_content (page, section, data) values ('contact', 'main', '{"heading":"Book a shoot","body":"Share a few details about your session or event and we will get back to you with availability and pricing.","responseNote":"Prefer to talk it through? WhatsApp is the fastest way to reach us."}'::jsonb);
insert into public.page_content (page, section, data) values ('work', 'header', '{"heading":"The work","body":"Weddings, portraits, celebrations and the city from above. A selection of recent sessions."}'::jsonb);
insert into public.page_content (page, section, data) values ('services', 'header', '{"heading":"What we do","body":"Nine services, one team. Book a single session or bring us in for the whole celebration."}'::jsonb);
