insert into public.albums (slug, title, category_id, summary, story, location, shot_on, cover, published, featured, sort_order) values ('olive-and-gold-engagement', 'Olive & Gold Engagement', (select id from public.categories where slug = 'weddings'), 'A traditional engagement in matching olive green, shot on a warm painted backdrop.', 'The couple chose one colour and committed to it, from the gele to the agbada. We kept the set simple so the fabric and beadwork could carry every frame.', 'Lagos', '2026-06-14'::date, '{"src":"https://images.unsplash.com/photo-1788035963488-cbfabe82ed4a","width":3851,"height":4814,"alt":"Couple in olive green traditional Nigerian wedding attire","credit":"McFollis"}'::jsonb, true, true, 1);
