insert into public.albums (slug, title, category_id, summary, story, location, shot_on, cover, published, featured, sort_order) values ('the-white-wedding', 'The White Wedding', (select id from public.categories where slug = 'weddings'), 'Lace, light and a very full day, from bridal prep to the last dance.', 'Two photographers covered the day: one with the bride from the morning, one with the groom and guests. The result is a full record of the day without anyone feeling watched.', 'Lekki, Lagos', '2026-04-25'::date, '{"src":"https://images.unsplash.com/photo-1645827042168-4fb0cdd0bf7e","width":3264,"height":4928,"alt":"Bride in a lace gown holding a bouquet of red roses","credit":"Oyemike Princewill"}'::jsonb, true, true, 2);
