insert into public.albums (slug, title, category_id, summary, story, location, shot_on, cover, published, featured, sort_order) values ('studio-portraits', 'Studio Portraits', (select id from public.categories where slug = 'portraits'), 'Low-key studio sessions for professionals, creatives and anyone who needs a picture that looks like them.', 'One backdrop, one or two lights, and enough time to get past the stiff first ten minutes. Most of these were made in under an hour.', 'UPC Studio, Lagos', '2026-05-02'::date, '{"src":"https://images.unsplash.com/photo-1605980776566-0486c3ac7617","width":3933,"height":5090,"alt":"Studio portrait of a man in a black turtleneck","credit":"Veroll Sterling"}'::jsonb, true, true, 5);
