insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('event-coverage', 'Event Coverage', 'Weddings, birthdays, launches and ceremonies, covered from arrival to last dance.', 'One or two photographers depending on the size of the day, with a clear shot list agreed in advance. You get a full edited gallery and the moments you would have missed.', '{"src":"https://images.unsplash.com/photo-1699730164892-d7c433524ff3","width":6989,"height":9318,"alt":"Guests raising glasses under balloons and confetti","credit":"OurWhisky Foundation"}'::jsonb, true, 1);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('videography', 'Videography', 'Highlight films and full-length edits with clean sound and steady footage.', 'From a three-minute highlight to a full ceremony edit, shot on cinema cameras with proper audio. Delivered ready to share.', '{"src":"https://images.unsplash.com/photo-1609034227505-5876f6aa4e90","width":3072,"height":3840,"alt":"Hand holding a camera lens under coloured light","credit":"Amari James"}'::jsonb, true, 2);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('photography', 'Photography', 'Documentary and editorial photography for people, places and brands.', 'Natural, well-lit images for personal milestones, corporate profiles and campaigns.', '{"src":"https://images.unsplash.com/photo-1551963319-13ff32a5acd1","width":6240,"height":4160,"alt":"Groom kissing the bride on her forehead outdoors","credit":"One zone Studio"}'::jsonb, true, 3);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('photoshoot', 'Photoshoot', 'Studio sessions for portraits, birthdays, couples and professional headshots.', 'A guided session in the studio with outfit changes, backdrop options and help with posing. Most sessions run about an hour.', '{"src":"https://images.unsplash.com/photo-1636144896336-b056be4a8dfe","width":2325,"height":3488,"alt":"Woman in a black suit lit in low light","credit":"Mo Darbz"}'::jsonb, true, 4);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('home-services', 'Home Services', 'We bring the studio to you, for families, newborns and elders who would rather stay home.', 'Portable lighting and backdrops set up in your living room, compound or garden. Ideal for family portraits and milestone birthdays.', '{"src":"https://images.unsplash.com/photo-1775688425905-a4539d6160da","width":3601,"height":5402,"alt":"Family posing in matching traditional clothing","credit":"Oswald Elsaboath"}'::jsonb, true, 5);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('photo-enlargement', 'Photo Enlargement', 'Large prints on paper and canvas, from desk size to statement walls.', 'Bring a file from us or anywhere else. We check the resolution, correct the colour and print it big.', '{"src":"https://images.unsplash.com/photo-1781208745207-e8a4c9985de7","width":7728,"height":5052,"alt":"Wall of framed photographs in a warm gallery","credit":"Cristian Pineda"}'::jsonb, true, 6);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('drone-piloting', 'Drone Piloting', 'Aerial photos and video for weddings, events, estates and construction progress.', 'Sweeping venue shots, guest arrivals and property overviews, flown safely and edited into your gallery or film.', '{"src":"https://images.unsplash.com/photo-1744907895363-d351aa6019ef","width":4032,"height":2268,"alt":"Aerial view of a bridge and lagoon in Lagos","credit":"Tunde Buremo"}'::jsonb, true, 7);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('photo-and-video-editing', 'Photo & Video Editing', 'Retouching, colour grading and video editing for footage shot by anyone.', 'Send us raw files from your own shoot and get back polished, consistent images or a finished edit.', '{"src":"https://images.unsplash.com/photo-1621024994278-e409544f4085","width":2997,"height":4504,"alt":"Photographer shooting with a DSLR in a dark studio","credit":"Colin Lloyd"}'::jsonb, true, 8);
insert into public.services (slug, title, summary, body, cover, visible, sort_order) values ('3d-frames', '3D Frames', 'Layered, dimensional frames that turn a favourite photo into a centrepiece.', 'Hand-built in our workshop in a range of finishes and sizes. Popular as gifts for weddings, birthdays and send-forths.', '{"src":"https://images.unsplash.com/photo-1789841418151-7a5b9a8812e6","width":3259,"height":2185,"alt":"Woman holding two framed prints against a wall","credit":"Barney Goodman"}'::jsonb, true, 9);
insert into public.packages (service_id, name, description, price_label, features, highlighted, visible, sort_order) values ((select id from public.services where slug = 'photoshoot'), 'Studio Session', 'Portraits, birthdays and professional headshots.', 'From ₦50,000', array['1 hour in studio', 'Up to 2 outfits', '10 retouched images', 'Online gallery']::text[], false, true, 1);
insert into public.packages (service_id, name, description, price_label, features, highlighted, visible, sort_order) values ((select id from public.services where slug = 'event-coverage'), 'Wedding Story', 'Traditional and white wedding, photo and film.', 'From ₦650,000', array['Two photographers and a videographer', 'Pre-wedding shoot', 'Highlight film and full edit', 'Drone coverage', '20x24 framed enlargement']::text[], true, true, 2);
insert into public.packages (service_id, name, description, price_label, features, highlighted, visible, sort_order) values ((select id from public.services where slug = 'event-coverage'), 'Event Coverage', 'Birthdays, launches, burials and ceremonies.', 'From ₦250,000', array['Up to 6 hours', 'Lead photographer and assistant', 'Full edited gallery', 'Optional highlight reel']::text[], false, true, 3);
insert into public.testimonials (client_name, context, quote, avatar, visible, sort_order) values ('Adaeze & Tunde', 'Traditional and white wedding', 'They were everywhere without being in the way. Our families still talk about the photos, and the framed print is the first thing people see in our home.', null, true, 1);
insert into public.testimonials (client_name, context, quote, avatar, visible, sort_order) values ('Mrs. Folake Adeyemi', '60th birthday at home', 'Ben set up in our living room and made my mother feel like a queen. Every picture came out beautiful and on time.', null, true, 2);
insert into public.testimonials (client_name, context, quote, avatar, visible, sort_order) values ('Chinedu Okafor', 'Corporate headshots', 'Quick, professional and patient with a team that hates cameras. The headshots look sharp on our website and LinkedIn.', null, true, 3);
